"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { PUBLIC_BASE_URL } from "@/api";
import { generateLineAudio } from "@/api/exercise";
import type Exercise from "@/interface/features/Exercise";

type Line = { audioIndex: number | null };

/** Plays one line of a reading / dictation: its stored clip, else a clip generated by the user's TTS endpoint
 *  (then stored on the exercise, so it is generated once). No browser voice: when TTS is missing or fails, `toast` warns. */
export function useLineAudio(exercise: Exercise) {
    const t = useTranslations("exercises");
    const [files, setFiles] = useState<string[]>(exercise.audio_files ?? []);
    const [indexes, setIndexes] = useState<Record<number, number>>({});   // line -> audioIndex learned in this session
    const [busy, setBusy] = useState<number | null>(null);
    const [warning, setWarning] = useState("");
    const timer = useRef<ReturnType<typeof setTimeout>>(undefined);

    useEffect(() => { setFiles(exercise.audio_files ?? []); setIndexes({}); setBusy(null); setWarning(""); }, [exercise]);
    useEffect(() => () => clearTimeout(timer.current), []);

    const warn = (message: string) => {
        setWarning(message);
        clearTimeout(timer.current);
        timer.current = setTimeout(() => setWarning(""), 5000);
    };
    const playFile = (path: string) => new Audio(PUBLIC_BASE_URL + path).play().catch(() => warn(t("audioPlayFailed")));

    const play = useCallback(async (lineIndex: number, line: Line) => {
        const stored = line.audioIndex ?? indexes[lineIndex];
        if (typeof stored === "number" && files[stored]) return void playFile(files[stored]);
        setBusy(lineIndex);
        try {
            const res = await generateLineAudio(exercise.id!, lineIndex);
            setFiles(res.audio_files);
            const generated = (res.content as { lines: Line[] }).lines[lineIndex].audioIndex;
            if (typeof generated === "number") {
                setIndexes((m) => ({ ...m, [lineIndex]: generated }));
                playFile(res.audio_files[generated]);
            }
        } catch (e) {
            warn(t((e as Error).message === "tts_not_configured" ? "ttsNotConfigured" : "ttsFailed"));
        } finally {
            setBusy(null);
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [exercise.id, files, indexes]);

    const toast = warning
        ? <p role="alert" className="bulk-toast bulk-toast-warn fixed bottom-6 left-1/2 z-50 -translate-x-1/2">{warning}</p>
        : null;
    return { play, busy, toast };
}
